/* Glue TU for the upstream round-trip test (roundTripTest.c).
 *
 * Upstream reads a file from argv and, at clevel 0, picks a compression
 * level from a content hash. Both inputs are pinned here: the buffer is
 * generated by a fixed LCG (mixing literal noise with repeated runs so it
 * is partially compressible) and the compression level is explicit.
 * roundTripCheck() exits nonzero on any mismatch.
 */
#define main lz4_upstream_roundtrip_unused_main
#include "roundTripTest.c"
#undef main

int harvest_roundtrip(int clevel, size_t size, unsigned seed)
{
    unsigned char *buf = (unsigned char *)malloc(size ? size : 1);
    unsigned state = seed;
    size_t i = 0;
    if (buf == NULL) return 100;
    while (i < size) {
        state = state * 2654435761u + 2246822519u;
        if ((state >> 28) < 6) {
            /* literal noise byte */
            buf[i++] = (unsigned char)(state >> 16);
        } else {
            /* compressible run: repeat one byte up to 31 times */
            size_t run = ((state >> 8) & 31) + 1;
            unsigned char b = (unsigned char)(state >> 20);
            while (run-- && i < size) buf[i++] = b;
        }
    }
    roundTripCheck(buf, size, clevel);
    free(buf);
    return 0;
}
